INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man: Championship Edition DX', 'PAC-MAN Championship Edition DX continues to uphold NAMCO BANDAI''s tradition of enhancing a classic franchise for today''s gamer. Building upon PAC-MAN Championship Edition’s original six courses, the new game features more than 100 varied and mind-boggling mazes to navigate. Several new modes will also be available to test a player''s pellet-munching aptitude. In Time Attack Mode, players will vie for the quickest clear time. Fulfill a series of objectives in Mission Mode or compete to devour the most number of ghosts gobbled in Ghost Mode.' FROM games WHERE igdb_id = 21737 ON CONFLICT (game_id, language_code) DO NOTHING;
