INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flight of the Icarus', 'Flight of the Icarus is a game where you play as a privateer who owns an airship that helps ferry goods from town to town in a post-apocalyptic world where the skies are dominated by pirates and danger. Shoot down enemy aeroplanes with a variety of deadly weaponry. Keep the ship from falling out the sky.' FROM games WHERE igdb_id = 9842 ON CONFLICT (game_id, language_code) DO NOTHING;
