INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flight Control HD', 'You’re an air traffic controller at an increasingly busy airport; just point and drag aircraft to their landing zones with your mouse or trackpad. Sounds easy? It isn’t! You’ll need nerves of steel and smart strategy to keep the chaos under control. Flight Control HD has been especially redesigned for PC and Mac, with updated graphics and an even tougher new challenge – the Steam exclusive Stunt map where you can increase your score by flying through the gates before landing.' FROM games WHERE igdb_id = 15064 ON CONFLICT (game_id, language_code) DO NOTHING;
