INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scott Pilgrim vs. the World: The Game', 'Scott Pilgrim vs. the World: The Game is a side-scrolling beat ''em up based on the Scott Pilgrim series. Play as the cast, who must battle through seven levels in order to defeat Ramona''s seven evil exes. Characters have their own individual movesets, which can be expanded upon by gaining enough experience, and are also able to use weapons.' FROM games WHERE igdb_id = 7448 ON CONFLICT (game_id, language_code) DO NOTHING;
