INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truth or Lies', 'In Truth or Lies, which is set for release this fall, players join family and friends in a roundtable style game play answering an astonishing array of thought-provoking questions. Utilizing a proprietary voice calibration system that works in conjunction with either the Xbox 360 Wireless Microphone or USB microphone, Truth or Lies measures stress levels in a player''s voice to reveal the honesty of their answers.' FROM games WHERE igdb_id = 25217 ON CONFLICT (game_id, language_code) DO NOTHING;
