INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heavy Rain', 'Heavy Rain is a cinematic psychological thriller from game developer Quantic Dream exclusively for the PlayStation 3. Dealing with a range of adult themes, the game revolves around a sophisticated plot and strong narrative threads that explore a complex moral proposition. You assume the role of multiple characters with very different backgrounds, motivations, and skills in a world where each player decision affects what will follow.' FROM games WHERE igdb_id = 493 ON CONFLICT (game_id, language_code) DO NOTHING;
