INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend of the Guardians: The Owls of Ga''Hoole', 'A companion game to the upcoming Legend of the Guardians: The Owls of Ga''Hoole theatrical release, this videogame will take players on an amazing adventure as they customize their very own Guardian owl and experience an airborne adventure like never before. Take on the role of a young Guardian and set out on a secret mission to uncover a new threat to the owl kingdom. Fly, race, fight off enemies, string together combos, and battle epic bosses throughout the mystical and magical world of Ga''Hoole.' FROM games WHERE igdb_id = 4968 ON CONFLICT (game_id, language_code) DO NOTHING;
