INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Harry Potter: Years 1-4', 'Experience the magic of Harry Potter''s first 4 years at Hogwarts School of Witchcraft and Wizardry in an exciting new way. LEGO Harry Potter: Years 1-4 combines the first four Harry Potter books and films in an interactive fun-filled videogame. Players can build the adventure from Privet Drive to the Triwizard Tournament through new LEGO gameplay elements like magical building and spell-casting.
