INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ProtoGalaxy', 'Earth is under siege! A mysterious and powerful alien race has come to enslave the entire galaxy, and your fleet is humanity''s last hope. You must put an end to the attacks and rebuild a home for the survivors. With the invaders in hot pursuit, and the dangers of the unexplored at every turn, do you have what it takes to forge a new galaxy?' FROM games WHERE igdb_id = 16194 ON CONFLICT (game_id, language_code) DO NOTHING;
