INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('date-warp', 17400, '2010-05-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3o6e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/m4yhug50x83xa5vxeing.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Date Warp', 'Time keeps slip, slip, slipping away...You''re trapped in a mansion with five guys, one of whom has a gun.There''s a giant countdown ticking down. At the end of this story, someone will die.Will it be you? Or can you escape... the DATE WARP?Use a steady hand to connect the wires and put the pieces together to solve the mystery of the mansion before it''s too late. Your choices will turn the story towards one of eleven possible endings.Characters: Janet - A freshman at Brook College, previously a socially-isolated student. Will she live or die? Alben - A mysteriously hostile young man. Why is he so angry? Bradley - A cheerful jock who''s been asking every freshman girl on exactly one date each. What is he planning? Linds - A lecherous scientist who is clearly up to something. What does he know about the forcefields? Nathaniel - A polite and wealthy gentleman offering assistance to those in need. But is that too convenient? Rafael - A soft-spoken young man who takes care of others but dodges questions about his past. Who is he working for?' FROM games WHERE igdb_id = 17400 ON CONFLICT (game_id, language_code) DO NOTHING;
