INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solatorobo: Red the Hunter', 'Set out on an adventure amid floating islands and witness a world brought to life by renowned designers and animators. Battle robot enemies, build your strength and undertake quests as you journey through the Shepherd Republic and meet fascinating characters. Take control of Red as he''s drawn into an epic tale and becomes responsible for the fate of the world. Compete with friends who own Solatorobo in all-action races round circuits floating in the sky.' FROM games WHERE igdb_id = 9597 ON CONFLICT (game_id, language_code) DO NOTHING;
