INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ModNation Racers', 'ModNation Racers is a Kart Racing game featuring all the track-based driving and comic combat players cherish in the genre, blended with extreme customization and user generated content expected of a modern online multiplayer title. In it, players can expect exceptional kart handling and physics technology, including drifting, jumps and boosting and easy to master customization options covering in-game racers, their karts and the tracks that are raced on.' FROM games WHERE igdb_id = 4841 ON CONFLICT (game_id, language_code) DO NOTHING;
