INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'America''s Next Top Model', 'You take control of one of 10 aspiring models that compete in a variety of different categories including: ''Make Up'', ''Fashion'', ''Catwalk'' and ''Photoshoot''. Following the same successful formula as the TV series, one model is dismissed each week following a special challenge; just make sure it''s not you! Choose your outfits in a variety of ways to live out the model lifestyle; be it striking a pose for a photographer, keeping your walk timed perfectly on the catwalk, or making sure your make-up is a match for the occasion. Talk to the other models in the apartment and get tips from your coach to help your performance during the week, then test your knowledge of the fashion industry in front of the panel each week to secure your place in the next round.' FROM games WHERE igdb_id = 50613 ON CONFLICT (game_id, language_code) DO NOTHING;
