INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yu-gi-oh-5ds-world-championship-2010-reverse-of-arcadia', 47841, '2010-03-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7yay.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! 5D''s World Championship 2010: Reverse of Arcadia', 'Yu-Gi-Oh! 5D''s World Championship 2010: Reverse of Arcadia''s story mode proceeds with a parallel story arch from the animated series involving the reprise of the Dark Signers and their quest for supremacy over New Domino City. After being banned to the Underworld, these Earthbound Immortals will stop at nothing to overthrow the rule of New Domino City and destroy Satellite. To defeat them, players will enlist the help of some of their favorite characters from the Yu-Gi-Oh! universe! Compete in story mode or free duel mode against Jack, Yusei or any of the 20 new characters to take on the Dark Signers in an epic battle to settle the score between light and dark!' FROM games WHERE igdb_id = 47841 ON CONFLICT (game_id, language_code) DO NOTHING;
