INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vancouver 2010', 'Experience the thrill and adrenaline of the Olympic Winter Games of Vancouver 2010. Carve your way down the slopes and across the ice as you aim to reach the pinnacle of your sport and claim a gold medal for your country. Featuring only the fastest, highest and most spectacular events that immerses the player in the adrenaline, danger and glory of the world’s greatest winter multi-sport event.' FROM games WHERE igdb_id = 2709 ON CONFLICT (game_id, language_code) DO NOTHING;
