INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kane & Lynch 2: Dog Days', 'Kane & Lynch 2: Dog Days is a raw and intense third person shooter designed to take players on an visceral story driven experience, following two of gaming''s most disturbed criminals through the gritty Shanghai underworld. Introducing a new visual experience, the design of Kane & Lynch 2: Dog Days has been inspired by documentary film-makers and the user-generated content era.' FROM games WHERE igdb_id = 488 ON CONFLICT (game_id, language_code) DO NOTHING;
