INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LittleBigPlanet: Sackboy''s Prehistoric Moves', 'Sackboy''s Prehistoric Moves is a LittleBigPlanet spin-off, which can be played with two to five players and requires a PlayStation Move controller and a PlayStation Eye Camera. One player uses the PlayStation Move motion controller as a pointing device to manipulate the environment by triggering switches and moving platforms, while the others play using a gamepad to control Sackboy in the usual way.' FROM games WHERE igdb_id = 6364 ON CONFLICT (game_id, language_code) DO NOTHING;
