INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunt the House: Terrortown', 'A side-scrolling action puzzle game starring ghosts! Leave the dusty halls of an abandoned clock tower to haunt your way through a town in the dead of night! Possess objects with your ghostly soul, to scare people away from a museum, a hospital, a theatre and a cruise ship. Will you be able to scare everyone out and reclaim what has been lost, before the night is over?' FROM games WHERE igdb_id = 16942 ON CONFLICT (game_id, language_code) DO NOTHING;
