INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'God Eater', 'God Eater is a Japanese action role-playing game and the first game in the God Eater series. The story revolves around the six members of the Far East Branch''s 1st Unit as part of a anti-Aragami organization called Fenrir. The game''s mission-based single-player mode consists of more than 100 missions, with co-operative play of up to three teammates over local adhoc wireless multiplayer or AI-controlled teammates.' FROM games WHERE igdb_id = 11844 ON CONFLICT (game_id, language_code) DO NOTHING;
