INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleach: Heat the Soul 7', 'Bleach: Heat the Soul 7 is a newest installment in the "Heat the Soul" series released on September 2, 2010. The main change in this game is a 4-Players mode.[10] Battles against giant characters have also been confirmed. New characters that have been announced are Allon (Ayon), Coyote Starrk (Los Lobos), Baraggan Luisenbarn (Arrogante), Tia Harribel (Tiburon), Yammy Riyalgo (Ira), Ulquiorra Cifer (Segunda Etapa), Ichigo Kurosaki (Full Hollow), Muramasa, Hachigen Ushoda, Love Aikawa and Shuren (downloadable content); in all, 84 characters are playable.' FROM games WHERE igdb_id = 66765 ON CONFLICT (game_id, language_code) DO NOTHING;
