INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Ice Cream', 'Bad Ice Cream is the first game in the similarly named series currently consisting out of 3 games. In each level you go around collecting fruit, whilest trying to avoid the enemies. You can also add and remove ice blocks in order to block enemies.' FROM games WHERE igdb_id = 106009 ON CONFLICT (game_id, language_code) DO NOTHING;
