INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('secret-of-the-magic-crystals', 10427, '2010-02-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86j6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qpcu6iq8escrsl9nvuci.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret of the Magic Crystals', 'In this game you manage a horse-breeding farm set in a fantasy surrounding. The game enables you to breed legendary horses such as Pegasus, Unicorn, Fire-steed, Ice-steed and Demon-steed. You can buy over 700 objects during the game. Make all kinds of horseshoes as well as lots of magical potions for your horses. If they are exhausted or ill, you are able to cure and look after them. Your horses and colts need lots of care and that’s the way they recover their strengths. You can train your horses on four different fields in five levels of difficulty. You can even breed them in order to have more talented horses. Different horse races help you to gather 25 kinds of cups and you can send your horses to complete 30 exciting missions.' FROM games WHERE igdb_id = 10427 ON CONFLICT (game_id, language_code) DO NOTHING;
