INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monday Night Combat', 'Monday Night Combat is a class-based, third-person shooter -- and the most popular lethal sport of the future! It blends intense combat, finishing moves, and game show-like challenges and rewards to produce an action experience unlike any other. Why fight for "honor" or "duty" when you can fight for the real American dream: cash, fame and endorsements?' FROM games WHERE igdb_id = 9660 ON CONFLICT (game_id, language_code) DO NOTHING;
