INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doodle God', 'Doodle God is a puzzle video game initially released for the iPhone/iPod Touch and subsequently released as a flash browser game, an Android game and a Windows Phone app. The Adobe Flash online browser game can be found on Armor Games. Version 1.1 was released on June 27, 2010. Doodle God''s gameplay is inspired by Russian online javascript game ''Alchemygame'' based on an old DOS game named ''Alchemy''.' FROM games WHERE igdb_id = 18528 ON CONFLICT (game_id, language_code) DO NOTHING;
