INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinect Joy Ride', 'Kinect Joy Ride combines classic karting with the controller-free gameplay of Kinect. Play five different game modes as you race through three different worlds with varied landscapes. Navigate obstacles, drift through corners and launch off jumps to wow your opponents with mid-air acrobatics. Then earn boosts, power-ups and other items to turn up the competition.' FROM games WHERE igdb_id = 2662 ON CONFLICT (game_id, language_code) DO NOTHING;
