INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BioShock 2', 'BioShock 2 is the second game of the BioShock series and the sequel to BioShock. It continues the grand storyline of the underwater metropolis Rapture. BioShock 2 capitalizes and improves upon the high-quality effects, unique gameplay elements, and immersive atmosphere that defined the first game. It explores more brutal gameplay than its predecessor, with new enemies, weapons, Plasmids, and Gene Tonics.' FROM games WHERE igdb_id = 21 ON CONFLICT (game_id, language_code) DO NOTHING;
