INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pound of Ground', 'Pound of Ground, story driven crazy shoot ''em up with red car and LOTS of zombies. The game combines action elements - a wide range of advanced weapons, fights with various bosses and spectacular, endless battles with the crowds of the undead - with a gripping story full of unexpected disclosures and peculiar characters.' FROM games WHERE igdb_id = 16030 ON CONFLICT (game_id, language_code) DO NOTHING;
