INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Galaxy 2', 'Super Mario Galaxy 2 is the sequel to Super Mario Galaxy and the fourth 3D platformer entry in the Mario franchise. The sequel retains many elements from its predecessor, such as the adventure being in outer space, the element of gravity, and recurring objects such as Launch Stars and Sling Stars. Returning items include the Bee Mushroom and the Fire Flower. However, the game introduces new elements as well, such as the utilization of Yoshi, new power-ups like the Cloud Flower, and the use of a guide within the game for beginner players.' FROM games WHERE igdb_id = 1078 ON CONFLICT (game_id, language_code) DO NOTHING;
