INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek Online', 'Star Trek Online is a premier free-to-play MMORPG from Cryptic Studios and Perfect World Entertainment set in the famous Star Trek universe. Don the official uniforms of the United Federation of Planets or the Klingon Empire, choose the path of Tactical, Science, or Engineering specialties, command Away Teams, captain your very own starship, avoid Borg assimilation, even breed Tribbles, all in Gene Roddenberry’s larger-than-life space epic, and all for free.' FROM games WHERE igdb_id = 7584 ON CONFLICT (game_id, language_code) DO NOTHING;
