INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman: The Brave and the Bold - The Videogame', 'The Brave and the Bold the Videogame fully immerses fans into the vivid animated world of the successful TV series where kids can play as Batman or together with family and friends in two-player co-op mode. Players can choose from iconic characters Robin, Green Lantern, Blue Beetle, along with drop-in heroes such as Aquaman to help solve puzzles and fight foes.' FROM games WHERE igdb_id = 4707 ON CONFLICT (game_id, language_code) DO NOTHING;
