INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atelier-totori-the-adventurer-of-arland', 7276, '2010-06-24', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xqc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fx3oyhme1efkhw2ahf53.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atelier Totori: The Adventurer of Arland', 'Atelier Totori: The Adventurer of Arland is a Japanese role-playing video game developed by Gust. It takes the series alchemy driven gameplay and expands it towards encouraging exploration and discovery. Atelier Totori is the twelfth installment in the Atelier series, and it continues the series'' emphasis on item synthesis. The game is the second in the Arland series and a direct sequel to Atelier Rorona: The Alchemist of Arland, taking place five years after the end of Atelier Rorona. It is followed by Atelier Meruru: The Apprentice of Arland.' FROM games WHERE igdb_id = 7276 ON CONFLICT (game_id, language_code) DO NOTHING;
