INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace Combat: Joint Assault', 'Joint Assault retains the basic gameplay from its predecessor, but with significant additions and alterations. Aerial combat adopts a visual system called "Enhanced Combat View" to alter the perspective of enemy aircraft close to the player, altering their size to make them appear much closer as a precursor to Dogfight Mode from Ace Combat: Assault Horizon.' FROM games WHERE igdb_id = 14757 ON CONFLICT (game_id, language_code) DO NOTHING;
