INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Racquet Sports', 'For the first time, Racquet Sports serves up 5 of your favorite racquet games all in one. Players are immersed in stunning worldwide locations as they serve, rally and smash their way to the finals. Every family member can get into the action with easy-to-use controls that precisely simulate each player''s movements. From Party Mode to Championship Mode, Racquet Sports is fun for everyone!' FROM games WHERE igdb_id = 51060 ON CONFLICT (game_id, language_code) DO NOTHING;
