INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little League World Series Baseball 2010', 'The Games on Demand version supports English. Swing for the fences this season with Little League World Series Baseball 2010! Little League welcomes you to the baseball diamond for the first time ever with easy to pick-up-and-play control mechanics that get you right into the action. Play your way from league champions to the regional tournament and, if you have what it takes, go all the way to the World Series in Williamsport, PA! Endless gameplay features that include team and player customization, collectibles, realistic 3D stadiums, talents, skill challenges and more fun than ever for the entire family!' FROM games WHERE igdb_id = 66621 ON CONFLICT (game_id, language_code) DO NOTHING;
