INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diner Dash 5: Boom!', 'When a sneaky prankster removes the word "fat" from Flo''s "Fat Free Breakfast" sign, a huge wave of hungry DinerToons overrun the diner causing it to explode! It''s up to Flo, the spunky waitress, to move outside the diner and serve food to customers anywhere and everywhere she can! Find creative places to seat customers, take on outdoor disasters, and do everything in your power to keep customers happy. Can you keep up with the demand and earn enough money to rebuild and decorate a new diner from scratch, or is Flo''s Diner gone forever?' FROM games WHERE igdb_id = 86687 ON CONFLICT (game_id, language_code) DO NOTHING;
