INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s H.A.W.X 2', 'Aerial warfare has evolved. So have you. As a member of the ultra-secret H.A.W.X. 2 squadron, you are one of the chosen few. One of the truly elite. You will use finely honed reflexes, bleeding-edge technology and ultra-sophisticated aircraft – their existence denied by many governments – to dominate the skies.' FROM games WHERE igdb_id = 984 ON CONFLICT (game_id, language_code) DO NOTHING;
