INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DanceMasters', 'The ultimate dance club right in your living room! DanceMasters is truly an evolution in dancing games. Dance freely using your body to match on-screen poses and specially choreographed moves. The game has over 30 songs to pick from, including hip hop, R&B, dance, pop and eurobeat. Dance Evolution also has an online mode, where you can challenge up to 4 friends at the same time. The various difficulties makes it easy for gamers and dancers of all levels to join in. You pick if you want to dance for fun, or make it into a tough workout.' FROM games WHERE igdb_id = 20121 ON CONFLICT (game_id, language_code) DO NOTHING;
