INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-scribblenauts', 8808, '2010-10-12', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co543g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ttp3ykvswddoef2f63mx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Scribblenauts', 'In this new game created and developed by 5TH Cell, players use the stylus and touch screen to help Maxwell, the game''s hero, acquire the "Starite," the prize earned from solving the puzzle in even more robust challenges and redesigned levels. Players now have the ability to write any object that comes to mind and modify it in any way they desire using adjectives to reach the goal in each level. Adjectives can change the color, size, elements, behaviors and many other aspects of the object they are describing. Multiple adjectives can be combined together to produce incredibly creative objects, allowing the player''s imagination to run wild for a truly unique and individualistic experience.' FROM games WHERE igdb_id = 8808 ON CONFLICT (game_id, language_code) DO NOTHING;
