INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('matt-hazard-blood-bath-and-beyond', 47430, '2010-01-07', 64, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5hwi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scalle.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Matt Hazard: Blood Bath and Beyond', 'Matt Hazard: Blood Bath and Beyond is designed as a 2D side scroller in order to give it a retro feel. You once again take on the role of Matt Hazard, parodying gaming clichés. In order to stop the evil Marathon MegaCorp from consigning Matt to certain death, he must travel back in time to stop them. In order to deal with the minions of Marathon, Matt will have an arsenal of standard weapons at his disposal that includes shotguns, plasma rifles, flamethrowers and grenades, which can be upgraded as the game progresses, you will also be able to find various power ups that will aid Matt''s quest. The shoulder buttons also allow you to enter the precision aim mode, which allows you to conserve your limited ammunition.
