INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Rising 2', 'As Chuck Greene, you have 72 hours to save your infected daughter, clear your name and survive the hordes of hungry zombies before the military comes in and nukes the city. To ensure your survival, you can combine everyday objects to create numerous deadly combo weapons and slaughter the ravenous zombies. Dead Rising 2, it’s where Creativity Kills.' FROM games WHERE igdb_id = 496 ON CONFLICT (game_id, language_code) DO NOTHING;
