INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'White Knight Chronicles II', 'White Knight Chronicles II, the sequel to White Knight Chronicles: International Edition, is an epic role-playing game available exclusively on the PlayStation 3 computer entertainment system. The game masterfully blends the cinematic storytelling of a single player role-playing game (RPG) with an entertaining and interactive co-op multiplayer RPG experience. From famed Japanese developer LEVEL-5, White Knight Chronicles II, features stunning graphics, over 400 new weapons and armors, and new skills and spells that make battles more interactive, strategic, and fast-paced. In addition to the full sequel, the game also includes the remastered White Knight Chronicles: International Edition as a bonus, delivering two full games and over 100 hours of combined gameplay.' FROM games WHERE igdb_id = 7483 ON CONFLICT (game_id, language_code) DO NOTHING;
