INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WRC: FIA World Rally Championship', 'WRC - FIA World Rally Championship is a car racing video game based on the 2010 season of the World Rally Championship (WRC). It is the first game to be officially licensed by the WRC since 2005''s WRC: Rally Evolved, and is the seventh game to bear the WRC license. The game was developed by Milestone S.r.l. and published by Black Bean Games. It was released in Australia on October 7, 2010, October 8, 2010 in Europe, and April 14, 2011 in Japan for Microsoft Windows, PlayStation 3 and Xbox 360 platforms. The developer had also created Superstars V8 Racing and Alfa Romeo Racing Italiano.
