INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku: Project Diva 2nd', 'Hatsune Miku: Project DIVA 2nd is a rhythm game and a sequel to the 2009 title, Hatsune Miku: Project DIVA. Like the original the game primarily makes use of Vocaloids, a series of singing synthesizer software, and the songs created using these vocaloids most notably the virtual-diva Vocaloid Hatsune Miku. In addition, a companion game Hatsune Miku: Project DIVA Dreamy Theater 2nd that allows players to play the game on the PlayStation 3 with improved visuals. There are a total of 66 songs available in Hatsune Miku: Project Diva 2nd.' FROM games WHERE igdb_id = 11755 ON CONFLICT (game_id, language_code) DO NOTHING;
