INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turba', 'Turba provides a gameplay experience unlike any you have encountered before. Load in music from your PC and combo blocks to your favorite tunes in this unique new twist on the "match-3" style game! The blocks on the game board generate and move to the beat of the song you choose. Clear blocks in time with the beat and make expert combos to maximize your score while you compete in online leaderboards for any and every song you play.' FROM games WHERE igdb_id = 16191 ON CONFLICT (game_id, language_code) DO NOTHING;
