INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wii Party', 'Wii Party features 13 different game modes divided amongst three categories: Party Games, House Party Games, and Pair Games. Most of the game modes integrate use of Wii Party''s 80 mini-games. The game also offers additional modes that make exclusive use of the mini-games.' FROM games WHERE igdb_id = 2189 ON CONFLICT (game_id, language_code) DO NOTHING;
