INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yet Another Zombie Defense', 'Yet Another Zombie Defense is an unusual mix of dual-stick zombie shooter and tower defense genres. The player is free to choose from nine unique weapons and mount them onto auto turrets or set up defensive barricades to stay alive as long as he can. There are also power-ups to collect, different zombie types to shoot at and cooperative mode.' FROM games WHERE igdb_id = 9201 ON CONFLICT (game_id, language_code) DO NOTHING;
