INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinect Adventures', 'Kinect Adventures! is a sports video game released by Microsoft Game Studios for the Xbox 360. Released in 2010, it is a collection of five adventure and sports minigames and was developed by Good Science Studio, a subsidiary of Microsoft Game Studios. The game utilizes the Kinect motion camera and was offered as a pack-in game with the console. It was officially unveiled at the 2010 Electronic Entertainment Expo in Los Angeles and went on to become the best selling game on the Xbox 360, selling 24 million units worldwide.' FROM games WHERE igdb_id = 2657 ON CONFLICT (game_id, language_code) DO NOTHING;
