INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Bros. Crossover', 'Super Mario Bros. Crossover is a fan-made crossover platform Flash video game launched on Newgrounds on April 27, 2010 by Exploding Rabbit. It is based mostly on the gameplay of Nintendo''s Super Mario Bros. for the NES. The only major difference is the ability to control characters that debuted in other Nintendo Entertainment System games unrelated to the Mario series. The latest version available (3.1) was released on December 25, 2013.' FROM games WHERE igdb_id = 8734 ON CONFLICT (game_id, language_code) DO NOTHING;
