INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost in Shadow', '"Lost in Shadow" (released as "A Shadow''s Tale" in Europe/Australia and as "Kage no Tou" in Japan) is a puzzle platforming video game developed for Nintendo''s Wii console by Hudson Soft. It was released in Japan in July 2010, in Australia and Europe in October 2010, and in North America in January 2011. It was also released for Wii U via Nintendo eShop in 2016.
