INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlazBlue: Continuum Shift II', 'BlazBlue: Continuum Shift II is a 2D fighting game and the enhanced version of BlazBlue: Continuum Shift. It features all the console exclusive characters, numerous balance changes, and other cosmetic changes such as a new announcer. Continuum Shift II was released as a free downloadable update for both PlayStation 3 and Xbox 360 versions of BlazBlue: Continuum Shift. The PlayStation Portable and Nintendo 3DS ports of the game include all the characters released as downloadable content with possible new story elements for them, a new mode called "Abyss", and balance tweaks as well.' FROM games WHERE igdb_id = 11611 ON CONFLICT (game_id, language_code) DO NOTHING;
