INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Central', 'Featuring full-body tracking, the magic of Kinect for Xbox 360 allows you to experience real dance with your friends and family. Whether you''re rehearsing in Break It Down! or owning the stage in Perform It, you''ll be introduced to more than 600 moves in the game and more than 90 dance routines all created by professional choreographers.
