INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joe Danger', 'Can you put the world’s most determined stuntman back into the limelight? Combo, boost and pull ludicrous stunts as Joe attempts to race his way back into the record books in over 100 eye-popping levels. Leap school buses full of screaming kids and pools of ravenous sharks! Dodge spikes and mousetraps! Speed through coin dashes and beat Team Nasty in nip-and-tuck races!' FROM games WHERE igdb_id = 11240 ON CONFLICT (game_id, language_code) DO NOTHING;
