INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grease', 'The Grease video game for Wii is a unique way for fans of the classic musical to sing and dance with friends and family alongside Danny Zuko, Sandy Olsson, The Pink Ladies and the T-Birds. Designed as a truly interactive experience, the game supports the Wii Remote, Wii compatible USB microphones and the Wii Balance Board. Additional features include a Party mode full of mini-games set within your favorite Grease moments, a Story mode where you sing and dance to win the heart of Sandy and 16 songs made famous by the movie and stage production.' FROM games WHERE igdb_id = 4895 ON CONFLICT (game_id, language_code) DO NOTHING;
