INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: Harmony of Despair', 'Castlevania: Harmony of Despair is a crossover platform-adventure game that features a new map system which allows players to see the current quest map''s entire setup, as well as up to six players at once over Xbox Live. The game was first leaked as an OFLCA Rating on May 27, 2010, then officially announced for Xbox Live Summer of Gaming 2010. Later in the year, the game was unveiled as a playable demo in the Konami booth at the E3 Convention of 2010.' FROM games WHERE igdb_id = 1147 ON CONFLICT (game_id, language_code) DO NOTHING;
