INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('melty-blood-actress-again-current-code', 19943, '2010-07-29', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2k5a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfpm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melty Blood Actress Again Current Code', 'The Sega RingWide and Windows port of Melty Blood Actress Again, originally for the PS2, updated with new characters, a rebalanced roster and some gameplay tweaks. It is the last game in the original Melty Blood series which follows the events of Tsukihime. Melty Blood Actress Again Current Code is an anime fighter with a strong emphasis on movement and featuring Moon styles, giving each of the 31 characters in the roster three different movesets with differing system mechanics. The Arcade mode has the same story as Actress Again, with the addition of new stories for characters new to Current Code (Powered Ciel and Archetype-Earth), duo characters who were without one (Neco & Mech and Kohaku & Mech), and Riesbyfe Stridberg, who gained an unlockable alternative route.' FROM games WHERE igdb_id = 19943 ON CONFLICT (game_id, language_code) DO NOTHING;
