INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ball', 'The Ball is a first person action-adventure game featuring a full single-player experience. As a swashbuckling archaeologist working on the slopes of a dormant volcano somewhere in Mexico, you get stuck in a cavern. It doesn''t take long before you realize this is more than just a cave.' FROM games WHERE igdb_id = 9402 ON CONFLICT (game_id, language_code) DO NOTHING;
