INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Greed Corp', 'Greed Corp is an award winning, innovative turn-based strategy game, situated in a rich, fictional world inspired by the industrial revolutions and their destructive effects on the environment. Find the delicate balance between harvesting the land for resources and preserving it to stay alive. Will you defend your territory or sacrifice it to keep it out of enemy hands? Manage the finite available resources to build your army and use the collapsing terrain to your advantage.' FROM games WHERE igdb_id = 16170 ON CONFLICT (game_id, language_code) DO NOTHING;
