INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zen Bound 2', 'Wrap your way to bliss in Zen Bound 2, the unique down-tempo indie game! This is a different gaming experience: an opportunity to slow down, zone out and focus on a task that''s challenging but not stressful, a set of gentle puzzles for the mind and fingers to solve. Enjoy a calm and meditative gameplay experience, with tactile, dusty visuals and a sublime, enveloping soundtrack by the sensational electronic artist Ghost Monkey.' FROM games WHERE igdb_id = 15063 ON CONFLICT (game_id, language_code) DO NOTHING;
