INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arsenal of Democracy', 'Taking you from 1936-64 you are able to play as any Nation in the WW2 era with detailed Economics, Diplomacy, Research, Intelligence and of course Warfare in the three branches of Land, Air and Sea. It Builds on the Experience and community Input of the previous successfully HOI Titles.Developed by BL-Logic, a development studio made up by fans of the Hearts of Iron series and active member of the modding community, Arsenal of Democracy is the ultimate World War II simulation and is described by Project Leader Lennart Berg as “Hearts of Iron II on steroids!”' FROM games WHERE igdb_id = 2009 ON CONFLICT (game_id, language_code) DO NOTHING;
