INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blacklight-tango-down', 8481, '2010-07-07', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6f3u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xttkzhxdnfry2irowhnf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blacklight: Tango Down', 'In Blacklight: Tango Down, experience the bleeding edge of advanced warfare. Participate in the “NetWar”: a hyper-realistic battlefield letting you fight tomorrow’s conflicts with or against your friends in the gritty Blacklight universe. Make your stand across seven game modes with 12 different maps in intense online battles supporting up to 16 players. Or fight through four intense Black Ops missions co-operatively or alone; all the while gaining experience, collecting stats, and unlocking items. Earn new weapon attachments and items, improve your abilities, and engage your Hyper Reality Visor to locate enemies and take them out. Customize your character and weaponry from among thousands of combinations to become the soldier you always wanted to be.' FROM games WHERE igdb_id = 8481 ON CONFLICT (game_id, language_code) DO NOTHING;
