INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guardians of Graxia', 'Guardians of Graxia takes on the form of a card-based board game set in a floating island environment high in the sky of the Graxia world. Releasing with four powerful Guardians that will guide your armies into battle, charge onto the battlefield by laying out your forces strategically. Gameplay advances in turns by selecting new unit and spell cards to place and move on the tiled map surface. Win by completing any of the numerous skirmishes, or by defeating Draknal Trueblood in the game''s initial campaign!' FROM games WHERE igdb_id = 16225 ON CONFLICT (game_id, language_code) DO NOTHING;
