INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flick Kick Football', 'With intuitive swipe-to-shoot control, Flick Kick Football is easy to play, but challenging to master! Flick your finger to curve, lob, drive and shoot the ball from all over the pitch. Test your skills in multiple modes, including Bullseye Mode and Time Attack! Update your team kit, ball, and fans to show your true colors! Can you score the match-winning goal?' FROM games WHERE igdb_id = 89008 ON CONFLICT (game_id, language_code) DO NOTHING;
