INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Date or Ditch 2', 'A Java-based dating sim by Gameloft, Date or Ditch 2 spans 22 chapters in New York City, featuring eight romanceable characters, three mini-games, and multiple endings. Gameplay centers on conversational choices (via icons) and building up (or tanking) relationships. Its lighthearted storyline, stylish presentation, and replay value make it feel like an extended romantic dinner rather than a fleeting encounter.' FROM games WHERE igdb_id = 239468 ON CONFLICT (game_id, language_code) DO NOTHING;
