INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bejeweled Blitz', 'Enjoy one minute of explosive match-3 fun from PopCap Games! Detonate as many gems as you can, 60 action-packed seconds at a time, in the hit puzzle game played by over 125 million people worldwide. Match three or more and create cascades of awesome with Flame gems, Star gems, and Hypercubes. Use powerful Rare Gems and upgradable Boosts to compete against friends, or challenge other players and top the leaderboards in Blitz Champions.' FROM games WHERE igdb_id = 20435 ON CONFLICT (game_id, language_code) DO NOTHING;
