INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robin''s Quest: A Legend Born', 'When an evil ruler greedily taxes his people to near starvation, there''s always one who rises against all odds to fight for what''s right... but Fighting for the good of the people often results in fighting for one''s family. Help our brave new Hero rise from humble beginnings to becoming the champion of which stories are written for centuries.' FROM games WHERE igdb_id = 17223 ON CONFLICT (game_id, language_code) DO NOTHING;
