INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flight-control', 15103, '2010-02-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co84h1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/g5slhhtyjrjv5mvhlgwx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flight Control', 'Air traffic control is the world''s most stressful job, but not for you. You don''t need heading angles, flight rules or meteorological reports, you''re a natural! A prodigy! A born controller! - Incredibly easy to learn! Just touch and drag the aircraft to their landing zones and avoid collisions.- Insanely addictive – it only takes a minute to get started, but it’s impossible to stop!-NEW - Fly solo, or share landing duties with a friend - online via Game Center on iOS4.2, over local Wi-Fi network or Bluetooth- NEW - Turn on the voice chat option to talk with the other controller when in online multiplayer mode (off by default)-Aim for a new personal best or compete against other Flight Controllers in online leaderboards- Earn achievements when you complete challenges - Visit all 5 airfields including Beach, Original, Windy, Australian Outback and Aircraft Carrier, each with unique characteristics and challenges!- Featuring 10 aircraft types including jets, helicopters and seaplanes!' FROM games WHERE igdb_id = 15103 ON CONFLICT (game_id, language_code) DO NOTHING;
