INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Expedition: Amazon', 'Big Fish Games Studios takes you on an Adventure into the stunning world of the Amazon with the Hidden Expedition team in search of a missing professor. A tattered map referencing the legendary Beetle Temple is your only clue as you begin your adventure deep into the Amazon Rain forest. Explore cities, temples, and ruins while unlocking the secrets of an ancient yet advanced civilization. This adventure is the largest yet for the Hidden Expedition team, and the discovery of the Beetle Temple is just the beginning.' FROM games WHERE igdb_id = 16176 ON CONFLICT (game_id, language_code) DO NOTHING;
