INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Active Life: Explorer', 'Jump into action as a fearless adventurer searching for treasure the world over. Explore an array of intriguing themed locales including dense twilight jungles, ancient ruins, lava-flooded caves, frozen ice packs and more each with their own traps, hazards and challenges. A veritable thrill-ride of activities will keep the whole family moving as they run across falling bridges, dodge perilous booby traps, escape from savage beasts, chase down bandits, and much more as they ride off into the sunset with a bounty of loot and rewards.' FROM games WHERE igdb_id = 4659 ON CONFLICT (game_id, language_code) DO NOTHING;
