INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High School Hook Ups', 'In Gameloft''s mobile adaptation of the dreaded high school years, your objective is to finish high school with the best reputation possible while developing as many friendships as you can. Experience a true-to-life high school experience thanks to typical characters and locations. Find the right words to seduce your love interest, but also to escape the bullies or convince the principal you didn''t commit that prank. Forget about grades, High School Hook Ups is all about finding the right one.' FROM games WHERE igdb_id = 239469 ON CONFLICT (game_id, language_code) DO NOTHING;
