INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Create', 'Create is a family-friendly puzzle-solving game where players must use their creativity to solve over-the-top, spatially based puzzles. Containing well over 100 puzzles from a variety of categories and set within several differently themed environments, Create allows players to let their imaginations run wild as they use virtually any object available to solve the unlikely challenges set before them. Additional features include extreme customization of game environments and the ability to share creations online with friends via Xbox LIVE.' FROM games WHERE igdb_id = 4778 ON CONFLICT (game_id, language_code) DO NOTHING;
