INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nimbus', 'Nimbus is a unique combination of racing & puzzling. The player controls a craft with no means of directly propelling itself and needs to use whatever is scattered around the levels to acquire thrust and reach the goal. Traverse a world map with several distinct islands in order to recover your lost love. Light on story, but heavy on gameplay Nimbus offers several hours of increasingly harder challenges.' FROM games WHERE igdb_id = 9561 ON CONFLICT (game_id, language_code) DO NOTHING;
