INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SBK X: Superbike World Championship', 'SBK-X: Superbike World Championship is a motorcycle racing game developed by Milestone s.r.l. and published by Black Bean Games in 2010. The game features three modes of gameplay: the arcade mode, the simulation mode and the multiplayer mode. Also for the first time in the series the game features the Superstock and Supersport championships. There are also the new career mode, composed of eight years, starting at the STK.' FROM games WHERE igdb_id = 7180 ON CONFLICT (game_id, language_code) DO NOTHING;
