INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Special Enquiry Detail: The Hand that Feeds', 'Help the Special Enquiry Detail crack the case, and catch a criminal, in this fun and exciting Hidden Object game! Join Detectives Turino and Lamonte, who have just been transferred to the Special Enquiry Detail unit. Their first case is the shocking death of the daughter of a wealthy family of benefactors. Dive into Special Enquiry Detail: The Hand that Feeds and become a New York City detective pursuing justice.' FROM games WHERE igdb_id = 87309 ON CONFLICT (game_id, language_code) DO NOTHING;
