INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ship Simulator Extremes', 'Ship Simulator Extremes is the revolutionary latest game in the best-selling Ship Simulator Series! It took almost 3 years to finish developing and features a brand new and dynamic weather system and a range of different vessels, from a lifeboat to a cruise ship! Explore different environments, such as the dangerous Antarctica or the luxurious Bora Bora! If free roaming massive environments is not your style, try a campaign mission; command a Greenpeace vessel, be in charge of a cruise ship on a round-the-world cruise or take massive industrial ships through stormy weather to make sure their merchandise gets to its destination!' FROM games WHERE igdb_id = 3209 ON CONFLICT (game_id, language_code) DO NOTHING;
