INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Razor2: Hidden Skies', 'Razor2: Hidden Skies Razor2: Hidden Skies is a top view shooter. The game has the style of successful classic arcade games, while using the latest technology to create great visuals and effects. An old-school game with all new technology. Razor2 has easy gameplay, while challenging your skills with hundreds of enemies and bullets threatening you all the time. The soundtrack is another great feature, Razor2 uses classic orchestrated music, composed especially for the game.' FROM games WHERE igdb_id = 14972 ON CONFLICT (game_id, language_code) DO NOTHING;
