INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizards of Waverly Place: Spellbound', 'Wizards of Waverly Place: Spellbound is a video game published by Disney Interactive Studios for the Nintendo DS, and released on November 16, 2010. The game is based on the popular Disney Channel show, Wizards of Waverly Place. There is another video game based on the show named: Wizards of Waverly Place, which was released on August 25, 2010 in America and on August 28, 2010 in Europe and Australia.' FROM games WHERE igdb_id = 24309 ON CONFLICT (game_id, language_code) DO NOTHING;
