INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Quest 2', 'Puzzle Quest 2 is a video game developed by Infinite Interactive for the Nintendo DS, Xbox Live Arcade, iOS, Android, Windows Phone 7, and Microsoft Windows. It was released on June 22, 2010 by D3 Publisher. It is the sequel to Puzzle Quest: Challenge of the Warlords, and like its predecessor, it combines role-playing with strategy and puzzle elements. It uses a competitive, Bejeweled-style, "match three game" playfield to simulate combat and other activities common to role-playing games.' FROM games WHERE igdb_id = 8979 ON CONFLICT (game_id, language_code) DO NOTHING;
