INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarioWare: D.I.Y. Showcase', 'WarioWare: D.I.Y. Showcase is intended as a showcase for all the different WarioWare: D.I.Y. products, including microgames, music, and four-panel comics - all with simple controls using only the Wii Remote controller. Use the Game Blender and its many modes to play microgames featuring Wario, ninjas, animals, and even classic Nintendo franchises. Or check out the Music section to listen to or play a selection of songs using a character from Balloon Fight.' FROM games WHERE igdb_id = 50705 ON CONFLICT (game_id, language_code) DO NOTHING;
