INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Hallway', 'Alien Hallway is a totally new action- strategy shooting game for the PC developed by Alien Shooter series makers, Sigma Team company. Here, in Sigma''s adrenaline-fueled game, players measure stamina with a never-ending stream of green creatures within the borders of a special military mission. The rules are severe and the fate of Humanity is put on the line.' FROM games WHERE igdb_id = 16246 ON CONFLICT (game_id, language_code) DO NOTHING;
